
@import url("https://fonts.googleapis.com/css2?family=Bungee&display=swap");
.station-notice-wrapper {
  display: flex;
  background: #2b2b4b;
  border-radius: 10px;
  margin: 10px;
  gap: 10px;
  padding: 5px 10px;
  justify-content: center;
  align-items: center;
  .volume { padding-top: 5px;}
  span { margin-right: 10px; cursor: pointer; }
}
.grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);

  margin: 10px auto;
  align-items: flex-start;
  gap: 10px;
  width: 95%;
  .q-card {
    margin: 0;
    background: #2b2b4b;
    // padding: 0px 50px;
    a {
      color: #ffffff;
    }
    .q-card__section {
      display: flex;
      align-items: center;
      // padding: 10px 0 0 10px;
      justify-content: flex-end;
      // height: calc(60vh / 3);
      overflow: hidden;
      svg {
        fill: #db7e42;
      }
      .livecasino-icon {
        transition: all 0.5s ease-in;
        border: 1px solid #ffffff;
        border-radius: 50%;
        width: 24px;
        height: 24px;
        border: 3px dotted #ffffff;
        font-size: 11px;
        text-align: center;
        line-height: 18px;
        margin: 0 auto;
      }
      .poker-icon {
        padding-left: 10px;
        .pokercards {
          // Outer wrapper for all cards
          position: relative; // Get control of the positioning
          // height: 18px; // height of each card
          // width: 15px; //width of each card
          // font-size: 10px; //size of number
          // line-height: 5px; //affects vert position of number
          height: 23px;
          width: 20px;
          font-size: 10px;
          line-height: 21px;
          font-weight: bold; //font weight
          .pokercard {
            transition: all 0.5s ease-in;
            display: flex;
            justify-content: center;
            align-items: center;
            color: #ffffff;
            // Common styles for all cards
            position: absolute; //Position all cards on top of each other
            width: 100%; //Expand to fill the parent's width
            height: 100%; //Expand to fill the parent's height
            border: 1px solid #ffffff; //card border width and color
            background: #212534;
            border-radius: 3px; //corner radius
            box-shadow: -2px 2px 3px rgba(0, 0, 0, 0.3); //Drop shadow position, size and color

            &.one {
              transform: translate(-5px, 0px) rotate(-10deg);
            }
            &.two {
            }
            &.five {
              transform: translate(-2px, 0px) rotate(10deg);
            }
          }
        }
      }
      .fish-icon {
        transition: all 0.5s ease-in;
        display: flex;
        align-items: center;
        height: 25px;
        &:before {
          content: "";
          border-top: 6px solid transparent;
          border-bottom: 6px solid transparent;
          border-left: 6px solid white;
          display: inline-block;
        }
        &:after {
          content: "";
          display: inline-block;
          border-radius: 50%;
          width: 16px;
          height: 12px;
          background: #ffffff;
        }
      }
      .slot-icon {
        transition: all 0.2s ease-in;
        font-size: 8px;
        line-height: 10px;
        font-weight: bold;
        position: relative;
        border: 0.5px solid #ffffff;
        padding: 2px;
        width: 30px;
        margin: 0 auto;

        span {
          border: 0.2px solid #ffffff;
          width: 8px;
          text-align: center;
          display: inline-block;
          &:before {
            content: "7";
          }
          &:first-child {
            border-right: 0;
          }
          &:last-child {
            border-left: 0;
          }
        }
      }
      svg {
        width: 25px;
        padding: 0;
        fill: #ffffff;
      }

      .text {
        position: absolute;
        left: 5px;
        text-align: center;
        justify-content: center;
        display: flex;
        flex-direction: column;
        align-items: center;
         width: 68px;
        // transform: scale(2);
      }
      img {
        width: 100%;
        // padding: 10px;
      }
    }
  }
}
@media (max-width: 400px) {
  .grid {
  .q-card {
    .q-card__section {
      .text {
        transform: scale(1.2);
      }
    }
  }
  }
}
